var wordBreak = function(s, wordDict) {
    const words = new Set(wordDict);
    let maxLength = 0;
    for (const w of words) maxLength = Math.max(maxLength, w.length);
    const memo = new Map();
    function build(start) {
        if (start === s.length) return [""];
        if (memo.has(start)) return memo.get(start);
        const sentences = [];
        const last = Math.min(s.length, start + maxLength);
        for (let end = start + 1; end <= last; end++) {
            const word = s.slice(start, end);
            if (!words.has(word)) continue;
            for (const suffix of build(end)) {
                sentences.push(suffix ? word + " " + suffix : word);
            }
        }
        memo.set(start, sentences);
        return sentences;
    }
    return build(0);
};

solution.python:
from functools import lru_cache
from typing import List


class Solution:
    def wordBreak(self, s: str, wordDict: List[str]) -> List[str]:
        words = set(wordDict)
        max_length = max((len(word) for word in words), default=0)

        @lru_cache(maxsize=None)
        def build(start: int):
            if start == len(s):
                return ("",)

            sentences = []
            last = min(len(s), start + max_length)
            for end in range(start + 1, last + 1):
                word = s[start:end]
                if word not in words:
                    continue
                for suffix in build(end):
                    sentences.append(word if not suffix else word + " " + suffix)
            return tuple(sentences)

        return list(build(0))
